/// height of the genesis block
pub const GENESIS_HEIGHT: u64 = 0;

/// required leading zero bits in the PoW digest
pub const INITIAL_DIFFICULTY_TARGET: u64 = 12;

/// hard cap on tx digests per block
pub const MAX_BLOCK_TXS: u64 = 256;


/// GENESIS_PREV: 32-byte all-zero parent hash carried by the genesis block.
pub const GENESIS_PREV: [u8; DIGEST_LEN] = [0u8; DIGEST_LEN];

/// Digest width in bytes for every chain hash (SHA-256).
pub const DIGEST_LEN: usize = 32;

pub type TxDigest = [u8; DIGEST_LEN];
pub type Hash = [u8; DIGEST_LEN];

// ── SHA-256 (FIPS 180-4) — provenance-copied strata-hash-pack pattern ──

const K: [u32; 64] = [
0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];


const H0: [u32; 8] = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
];

/// SHA-256 of `data`, per FIPS 180-4 §6.2.
pub fn sha256(data: &[u8]) -> Hash {
    let mut h = H0;
    let bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    for block in msg.chunks_exact(64) {
        let mut w = [0u32; 64];
        for (i, word) in block.chunks_exact(4).enumerate() {
            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
            (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    let mut out = [0u8; DIGEST_LEN];
    for (i, word) in h.iter().enumerate() {
        out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
    }
    out
}

/// One Merkle node: H(left || right), single SHA-256 per level (strata
/// family convention).
fn node_hash(left: &Hash, right: &Hash) -> Hash {
    let mut buf = [0u8; DIGEST_LEN * 2];
    buf[..DIGEST_LEN].copy_from_slice(left);
    buf[DIGEST_LEN..].copy_from_slice(right);
    sha256(&buf)
}

/// Level-width collapse with the duplicate-last (Bitcoin) odd rule.
fn collapse(level: &[Hash]) -> Vec<Hash> {
    let mut next = Vec::with_capacity((level.len() + 1) / 2);
    let mut i = 0;
    while i < level.len() {
        let right = if i + 1 < level.len() { level[i + 1] } else { level[i] };
        next.push(node_hash(&level[i], &right));
        i += 2;
    }
    next
}

/// Merkle root over ordered tx digests; the empty tx set commits to
/// SHA-256 of the empty byte string (deterministic, never `None`).
pub fn tx_merkle_root_for(txs: &[TxDigest]) -> Hash {
    if txs.is_empty() {
        return sha256(&[]);
    }
    let mut level: Vec<Hash> = txs.to_vec();
    while level.len() > 1 {
        level = collapse(&level);
    }
    level[0]
}

// ── Block model ───────────────────────────────────────────────────────

/// One chain block: header fields + the ordered tx digests it commits.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Block {
    /// Height: exactly parent.height + 1 for a valid child.
    pub height: u64,
    /// SHA-256 of the parent's header encoding; genesis carries GENESIS_PREV.
    pub parent_hash: Hash,
    /// Merkle commitment over the ordered tx digests.
    pub tx_merkle_root: Hash,
    /// Post-block state root (opaque commitment; S4 ledger owns the math).
    pub state_root: Hash,
    /// Required leading zero bits in the PoW digest.
    pub difficulty_target: u32,
    /// PoW nonce; also the fork-choice tiebreaker (lower wins).
    pub nonce: u64,
    /// Monotonic logical slot — never wall-clock (determinism law).
    pub timestamp_slot: u64,
    /// Ordered tx digests committed by this block.
    pub txs: Vec<TxDigest>,
}

impl Block {
    /// Canonical header encoding: height(u64 BE) || parentHash ||
    /// txMerkleRoot || stateRoot || difficulty(u32 BE) || slot(u64 BE).
    pub fn header_bytes(&self) -> Vec<u8> {
        let mut b = Vec::with_capacity(8 + 3 * DIGEST_LEN + 4 + 8);
        b.extend_from_slice(&self.height.to_be_bytes());
        b.extend_from_slice(&self.parent_hash);
        b.extend_from_slice(&self.tx_merkle_root);
        b.extend_from_slice(&self.state_root);
        b.extend_from_slice(&self.difficulty_target.to_be_bytes());
        b.extend_from_slice(&self.timestamp_slot.to_be_bytes());
        b
    }

    /// PoW digest: SHA-256(header encoding || nonce u64 BE).
    pub fn pow_hash(&self) -> Hash {
        let mut buf = self.header_bytes();
        buf.extend_from_slice(&self.nonce.to_be_bytes());
        sha256(&buf)
    }
}

/// Leading zero bit count of a digest (the deterministic PoW metric).
pub fn leading_zero_bits(h: &Hash) -> u32 {
    let mut n = 0u32;
    for byte in h {
        if *byte == 0 {
            n += 8;
        } else {
            n += byte.leading_zeros();
            break;
        }
    }
    n
}

/// The genesis block: height GENESIS_HEIGHT, all-zero parent hash,
/// empty tx set, slot 0, nonce 0.
pub fn genesis() -> Block {
    Block {
        height: GENESIS_HEIGHT,
        parent_hash: GENESIS_PREV,
        tx_merkle_root: tx_merkle_root_for(&[]),
        state_root: sha256(b"strata-genesis-state"),
        difficulty_target: INITIAL_DIFFICULTY_TARGET as u32,
        nonce: 0,
        timestamp_slot: 0,
        txs: Vec::new(),
    }
}

// ── Chain-validity law ────────────────────────────────────────────────

/// Typed chain refusal — every rejection is a named variant, never a bool.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ChainRefusal {
    /// Child height is not exactly parent.height + 1.
    HeightContinuity { expected: u64, got: u64 },
    /// parent_hash does not equal SHA-256 of the parent header encoding.
    ParentHashMismatch,
    /// Merkle root does not match the committed tx digests.
    MerkleRootMismatch { expected: Hash, got: Hash },
    /// More than MAX_BLOCK_TXS tx digests in one block.
    TxCapExceeded { max: u64, got: u64 },
    /// The same tx digest appears twice in one block.
    DuplicateTx { index: usize },
    /// Mined PoW digest does not meet the difficulty target.
    PoWTargetNotMet { required_bits: u32, got_bits: u32 },
    /// Child timestamp slot is lower than the parent's (monotonic law).
    SlotRegression { parent_slot: u64, got: u64 },
}

/// Validate `block` as a direct child of `parent` (full law: height
/// continuity, parent-hash binding, tx cap, duplicate-tx, merkle
/// commitment, monotonic slot, PoW re-check).
pub fn validate_block(parent: &Block, block: &Block) -> Result<(), ChainRefusal> {
    // Height continuity: a child is exactly one above its parent.
    if block.height != parent.height + 1 {
        return Err(ChainRefusal::HeightContinuity {
            expected: parent.height + 1,
            got: block.height,
        });
    }
    // Parent-hash binding: the digest of the parent header encoding.
    if block.parent_hash != sha256(&parent.header_bytes()) {
        return Err(ChainRefusal::ParentHashMismatch);
    }
    // Tx cap.
    if block.txs.len() as u64 > MAX_BLOCK_TXS {
        return Err(ChainRefusal::TxCapExceeded {
            max: MAX_BLOCK_TXS,
            got: block.txs.len() as u64,
        });
    }
    // Duplicate tx digests refused.
    for i in 0..block.txs.len() {
        for j in (i + 1)..block.txs.len() {
            if block.txs[i] == block.txs[j] {
                return Err(ChainRefusal::DuplicateTx { index: j });
            }
        }
    }
    // Merkle commitment over the ordered tx digests.
    let root = tx_merkle_root_for(&block.txs);
    if block.tx_merkle_root != root {
        return Err(ChainRefusal::MerkleRootMismatch {
            expected: root,
            got: block.tx_merkle_root,
        });
    }
    // Monotonic slot (logical, not wall-clock).
    if block.timestamp_slot < parent.timestamp_slot {
        return Err(ChainRefusal::SlotRegression {
            parent_slot: parent.timestamp_slot,
            got: block.timestamp_slot,
        });
    }
    // PoW re-check: the stored nonce must actually meet the target.
    let bits = leading_zero_bits(&block.pow_hash());
    if bits < block.difficulty_target {
        return Err(ChainRefusal::PoWTargetNotMet {
            required_bits: block.difficulty_target,
            got_bits: bits,
        });
    }
    Ok(())
}

// ── Mining ────────────────────────────────────────────────────────────

/// Deterministic PoW tick: starting at `block.nonce`, search at most
/// `attempts` consecutive nonces for one whose PoW digest meets the
/// difficulty target. On success, sets `block.nonce` and returns true.
/// Same starting seed + same target ⇒ same nonce, always (no RNG, no
/// wall-clock).
pub fn mine_tick(block: &mut Block, attempts: u64) -> bool {
    let start = block.nonce;
    for k in 0..attempts {
        block.nonce = start.wrapping_add(k);
        if leading_zero_bits(&block.pow_hash()) >= block.difficulty_target {
            return true;
        }
    }
    false
}

// ── Attach + fork choice ──────────────────────────────────────────────

/// Attach `block` to the tip of `chain`, validating it against the
/// current tip. On success the block is pushed; on refusal the chain is
/// untouched and the typed refusal returned.
pub fn attach(chain: &mut Vec<Block>, block: Block) -> Result<(), ChainRefusal> {
    let tip = match chain.last() {
        Some(t) => t.clone(),
        None => return Ok(()), // empty vector: the first block seeds the chain
    };
    validate_block(&tip, &block)?;
    chain.push(block);
    Ok(())
}

/// Deterministic fork choice over candidate chains: the longest chain
/// wins; equal-height ties resolve to the chain whose TIP has the lower
/// nonce. Returns the index of the winner.
pub fn fork_choice(chains: &[Vec<Block>]) -> Option<usize> {
    if chains.is_empty() {
        return None;
    }
    let mut best = 0usize;
    for (i, chain) in chains.iter().enumerate().skip(1) {
        let better = match (chain.last(), chains[best].last()) {
            (Some(c), Some(b)) => {
                c.height > b.height
                    || (c.height == b.height && c.nonce < b.nonce)
            }
            (Some(_), None) => true,
            _ => false,
        };
        if better {
            best = i;
        }
    }
    Some(best)
}

/// Identity of two blocks for fork purposes: same header encoding, same
/// tx set, same nonce.
fn blocks_equal(a: &Block, b: &Block) -> bool {
    a == b
}

/// Attempt a reorg from `current` to `candidate` under the fork-choice
/// law. If the candidate wins, returns the displaced suffix of `current`
/// (the blocks no longer on the selected chain). If it loses, returns
/// `None` and neither chain is touched.
pub fn reorg(current: &[Block], candidate: &[Block]) -> Option<Vec<Block>> {
    let cur_tip = current.last()?;
    let cand_tip = candidate.last()?;
    let candidate_wins =
        cand_tip.height > cur_tip.height || (cand_tip.height == cur_tip.height && cand_tip.nonce < cur_tip.nonce);
    if !candidate_wins {
        return None;
    }
    // Displaced = blocks on `current` that extend beyond the actual
    // shared prefix with `candidate` (blocks compared by their full
    // validity-relevant encoding, i.e. header bytes + tx set).
    let mut common = 0usize;
    let limit = candidate.len().min(current.len());
    while common < limit && blocks_equal(&current[common], &candidate[common]) {
        common += 1;
    }
    let mut displaced = Vec::new();
    for b in &current[common..] {
        displaced.push(b.clone());
    }
    Some(displaced)
}

// ── Tests ─────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn digest(seed: u8, n: usize) -> TxDigest {
        let mut d = [0u8; DIGEST_LEN];
        d[0] = seed;
        d[1] = n as u8;
        d[2] = (n >> 8) as u8;
        d
    }

    /// Build a mined child of `parent` committing `txs` at `slot`.
    fn mine_child(parent: &Block, txs: Vec<TxDigest>, slot: u64) -> Block {
        let mut child = Block {
            height: parent.height + 1,
            parent_hash: sha256(&parent.header_bytes()),
            tx_merkle_root: tx_merkle_root_for(&txs),
            state_root: sha256(&parent.state_root),
            difficulty_target: parent.difficulty_target,
            nonce: 0,
            timestamp_slot: slot,
            txs,
        };
        assert!(mine_tick(&mut child, 1 << 20), "mining must succeed");
        child
    }

    #[test]
    fn sha256_vectors() {
        // FIPS 180-4 published examples.
        assert_eq!(
            sha256(b"").to_vec(),
            hex("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855")
        );
        assert_eq!(
            sha256(b"abc").to_vec(),
            hex("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
        );
    }

    fn hex(s: &str) -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
            .collect()
    }

    #[test]
    fn genesis_shape() {
        let g = genesis();
        assert_eq!(g.height, GENESIS_HEIGHT);
        assert_eq!(g.parent_hash, GENESIS_PREV);
        assert_eq!(g.tx_merkle_root, sha256(&[]));
        assert_eq!(g.timestamp_slot, 0);
        validate_block(&g, &mine_child(&g, vec![], 1)).unwrap();
    }

    #[test]
    fn chain_of_five_valid() {
        let mut chain = vec![genesis()];
        for i in 0..5u64 {
            let parent = chain.last().unwrap().clone();
            let txs = vec![digest(0xA0, i as usize)];
            let child = mine_child(&parent, txs, i + 1);
            attach(&mut chain, child.clone()).unwrap();
        }
        assert_eq!(chain.len(), 6); // genesis + 5
        for w in chain.windows(2) {
            assert_eq!(w[1].height, w[0].height + 1);
            assert_eq!(w[1].parent_hash, sha256(&w[0].header_bytes()));
        }
    }

    #[test]
    fn invalid_parent_hash_refused() {
        let g = genesis();
        let mut child = mine_child(&g, vec![], 1);
        child.parent_hash = [7u8; DIGEST_LEN];
        match validate_block(&g, &child) {
            Err(ChainRefusal::ParentHashMismatch) => {}
            other => panic!("expected ParentHashMismatch, got {:?}", other),
        }
    }

    #[test]
    fn height_gap_refused() {
        let g = genesis();
        let child = mine_child(&g, vec![], 1);
        let mut grandchild = mine_child(&child, vec![], 2);
        // Skip a block: attach the grandchild to genesis.
        grandchild.height = g.height + 5;
        grandchild.parent_hash = sha256(&g.header_bytes());
        grandchild.tx_merkle_root = tx_merkle_root_for(&grandchild.txs);
        match validate_block(&g, &grandchild) {
            Err(ChainRefusal::HeightContinuity { expected, got }) => {
                assert_eq!((expected, got), (1, 5));
            }
            other => panic!("expected HeightContinuity, got {:?}", other),
        }
    }

    #[test]
    fn merkle_tamper_refused() {
        let g = genesis();
        let mut child = mine_child(&g, vec![digest(1, 1), digest(1, 2)], 1);
        child.tx_merkle_root = [0xEEu8; DIGEST_LEN];
        match validate_block(&g, &child) {
            Err(ChainRefusal::MerkleRootMismatch { .. }) => {}
            other => panic!("expected MerkleRootMismatch, got {:?}", other),
        }
    }

    #[test]
    fn dup_tx_refused() {
        let g = genesis();
        let mut child = mine_child(&g, vec![digest(2, 9), digest(2, 9)], 1);
        // Fix the merkle root so the duplicate arm is the one that fires.
        child.tx_merkle_root = tx_merkle_root_for(&child.txs);
        match validate_block(&g, &child) {
            Err(ChainRefusal::DuplicateTx { .. }) => {}
            other => panic!("expected DuplicateTx, got {:?}", other),
        }
    }

    #[test]
    fn tx_cap_refused() {
        let g = genesis();
        let mut child = mine_child(&g, (0..(MAX_BLOCK_TXS + 1) as usize).map(|i| digest(3, i)).collect(), 1);
        child.tx_merkle_root = tx_merkle_root_for(&child.txs);
        match validate_block(&g, &child) {
            Err(ChainRefusal::TxCapExceeded { max, .. }) => assert_eq!(max, MAX_BLOCK_TXS),
            other => panic!("expected TxCapExceeded, got {:?}", other),
        }
    }

    #[test]
    fn fork_choice_picks_longer_chain() {
        let g = genesis();
        let short = vec![g.clone(), mine_child(&g, vec![], 1)];
        let mut long = vec![g.clone()];
        for i in 0..3u64 {
            let parent = long.last().unwrap().clone();
            long.push(mine_child(&parent, vec![], i + 1));
        }
        assert_eq!(fork_choice(&[short.clone(), long.clone()]), Some(1));
        assert_eq!(fork_choice(&[long, short]), Some(0));
    }

    #[test]
    fn fork_tie_lower_nonce_wins() {
        // Two equal-height chains; mine nonces and force a tie-break.
        let g = genesis();
        let mut a = mine_child(&g, vec![digest(4, 1)], 1);
        let mut b = mine_child(&g, vec![digest(5, 1)], 1);
        if a.nonce > b.nonce {
            std::mem::swap(&mut a, &mut b);
        }
        // After the swap, `a` carries the lower nonce; craft both chains
        // so their tips are equal-height with those nonces.
        let chain_a = vec![g.clone(), a];
        let chain_b = vec![g.clone(), b];
        assert_eq!(fork_choice(&[chain_b, chain_a]), Some(1));
    }

    #[test]
    fn reorg_returns_displaced_blocks() {
        let g = genesis();
        let mut current = vec![g.clone()];
        for i in 0..2u64 {
            let parent = current.last().unwrap().clone();
            current.push(mine_child(&parent, vec![], i + 1));
        }
        // A longer competing chain from genesis (distinct txs — mining is
        // deterministic, so identical inputs would be the SAME chain).
        let mut candidate = vec![g.clone()];
        for i in 0..4u64 {
            let parent = candidate.last().unwrap().clone();
            candidate.push(mine_child(&parent, vec![digest(9, i as usize)], i + 1));
        }
        let displaced = reorg(&current, &candidate).expect("candidate must win");
        // Chains share only genesis; both of current's mined blocks are displaced.
        assert_eq!(displaced.len(), 2);
        // Losing candidate: reorg refuses.
        assert!(reorg(&candidate, &current).is_none());
    }

    #[test]
    fn pow_determinism() {
        let g = genesis();
        let mut b1 = Block {
            height: 1,
            parent_hash: sha256(&g.header_bytes()),
            tx_merkle_root: tx_merkle_root_for(&[]),
            state_root: sha256(b"x"),
            difficulty_target: INITIAL_DIFFICULTY_TARGET as u32,
            nonce: 0,
            timestamp_slot: 1,
            txs: vec![],
        };
        let mut b2 = b1.clone();
        assert!(mine_tick(&mut b1, 1 << 20));
        assert!(mine_tick(&mut b2, 1 << 20));
        assert_eq!(b1.nonce, b2.nonce, "same seed ⇒ same nonce");
        // And the found nonce really meets the target.
        assert!(leading_zero_bits(&b1.pow_hash()) >= INITIAL_DIFFICULTY_TARGET as u32);
        // A tick with the already-mined nonce returns immediately.
        assert!(mine_tick(&mut b1, 1));
        assert_eq!(b1.nonce, b2.nonce);
    }

    #[test]
    fn slot_regression_refused() {
        let g = genesis();
        // Parent slot 0 → mine a child at slot 3, then regress a
        // grandchild below the parent's slot.
        let c1 = mine_child(&g, vec![], 3);
        let mut c2 = mine_child(&c1, vec![], 4);
        c2.timestamp_slot = 2; // < c1's slot 3
        match validate_block(&c1, &c2) {
            Err(ChainRefusal::SlotRegression { parent_slot, got }) => {
                assert_eq!((parent_slot, got), (3, 2));
            }
            other => panic!("expected SlotRegression, got {:?}", other),
        }
    }

    #[test]
    fn projection_nonempty() {
        // Non-vacuity witness: the constants were really projected.
        assert_eq!(GENESIS_HEIGHT, 0);
        assert_eq!(MAX_BLOCK_TXS, 256);
        assert!(INITIAL_DIFFICULTY_TARGET > 0);
    }

    // ── Shared-head KAT court (L124) + chain_fold sabotage twin ────────
    //
    // Law (witness.ttl shared-head KAT, lane L9): the same four witnessed
    // entries folded by insa-proof's sync replay law and strata-protocol's
    // logchain law —
    //   h_0     = 32 bytes of 0x00
    //   h_{i+1} = BLAKE3(h_i || pn_be || ocel_be || tick_be64)
    //   tick    = top byte of the OCEL word, widened to u64 big-endian
    // fold the witnessed fixture to the pinned cross-repo head
    // 05ea1aa0... (verify.py pins the same literal).
    //
    // The in-test BLAKE3 below is the single-chunk core, PROVENANCE-COPIED
    // PATTERN from strata-hash-pack (same reuse discipline as this
    // module's FIPS 180-4 SHA-256); every fold input here is 56 bytes.
    // BLAKE3 (O'Connor et al., 2020) single-chunk core.

    fn blake3_compress(
        cv: [u32; 8],
        block_words: [u32; 16],
        block_len: u32,
        flags: u32,
    ) -> [u32; 16] {
        const IV: [u32; 8] = [
            0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A, 0x510E527F, 0x9B05688C, 0x1F83D9AB,
            0x5BE0CD19,
        ];
        const MSG_PERMUTATION: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];
        let mut state = [
            cv[0], cv[1], cv[2], cv[3], cv[4], cv[5], cv[6], cv[7], IV[0], IV[1], IV[2], IV[3],
            0, 0, block_len, flags,
        ];
        let mut m = block_words;
        fn g(s: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
            s[a] = s[a].wrapping_add(s[b]).wrapping_add(mx);
            s[d] = (s[d] ^ s[a]).rotate_right(16);
            s[c] = s[c].wrapping_add(s[d]);
            s[b] = (s[b] ^ s[c]).rotate_right(12);
            s[a] = s[a].wrapping_add(s[b]).wrapping_add(my);
            s[d] = (s[d] ^ s[a]).rotate_right(8);
            s[c] = s[c].wrapping_add(s[d]);
            s[b] = (s[b] ^ s[c]).rotate_right(7);
        }
        fn round(s: &mut [u32; 16], m: &[u32; 16]) {
            g(s, 0, 4, 8, 12, m[0], m[1]);
            g(s, 1, 5, 9, 13, m[2], m[3]);
            g(s, 2, 6, 10, 14, m[4], m[5]);
            g(s, 3, 7, 11, 15, m[6], m[7]);
            g(s, 0, 5, 10, 15, m[8], m[9]);
            g(s, 1, 6, 11, 12, m[10], m[11]);
            g(s, 2, 7, 8, 13, m[12], m[13]);
            g(s, 3, 4, 9, 14, m[14], m[15]);
        }
        for _ in 0..7 {
            round(&mut state, &m);
            m = {
                let mut next = [0u32; 16];
                for i in 0..16 {
                    next[i] = m[MSG_PERMUTATION[i]];
                }
                next
            };
        }
        for i in 0..8 {
            state[i] ^= state[i + 8];
            state[i + 8] ^= cv[i];
        }
        state
    }

    fn to_words(block: &[u8; 64]) -> [u32; 16] {
        let mut m = [0u32; 16];
        for (i, w) in m.iter_mut().enumerate() {
            *w = u32::from_le_bytes([
                block[i * 4],
                block[i * 4 + 1],
                block[i * 4 + 2],
                block[i * 4 + 3],
            ]);
        }
        m
    }

    fn hex32(bytes: &[u8]) -> String {
        bytes.iter().map(|b| format!("{b:02x}")).collect()
    }

    /// BLAKE3 over a single-chunk (< 1024 byte) input; multi-chunk inputs
    /// are outside this court's domain and refuse loudly.
    fn blake3_single_chunk(input: &[u8]) -> [u8; DIGEST_LEN] {
        const CHUNK_START: u32 = 1 << 0;
        const CHUNK_END: u32 = 1 << 1;
        const ROOT: u32 = 1 << 3;
        assert!(
            input.len() < 1024,
            "shared-KAT court domain: single-chunk BLAKE3 only (input < 1024 bytes, got {})",
            input.len()
        );
        let mut cv = [
            0x6A09E667u32, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A, 0x510E527F, 0x9B05688C, 0x1F83D9AB,
            0x5BE0CD19,
        ];
        let mut block = [0u8; 64];
        let mut block_len = 0usize;
        let mut flags = CHUNK_START;
        let mut pos = 0usize;
        while pos < input.len() {
            if block_len == 64 {
                let out = blake3_compress(cv, to_words(&block), block_len as u32, flags);
                cv = [out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7]];
                block = [0u8; 64];
                block_len = 0;
                flags = 0;
            }
            let take = (64 - block_len).min(input.len() - pos);
            block[block_len..block_len + take].copy_from_slice(&input[pos..pos + take]);
            block_len += take;
            pos += take;
            if pos == input.len() {
                flags |= CHUNK_END | ROOT;
            } else if block_len == 0 {
                flags |= CHUNK_START;
            }
        }
        if input.is_empty() {
            flags |= CHUNK_END | ROOT;
        }
        let out = blake3_compress(cv, to_words(&block), block_len as u32, flags);
        let mut digest = [0u8; DIGEST_LEN];
        for (i, w) in out[..8].iter().enumerate() {
            digest[i * 4..i * 4 + 4].copy_from_slice(&w.to_le_bytes());
        }
        digest
    }

    /// One witnessed KAT fixture entry: (pn, ocel). Mirrors the
    /// sw:kat-entry-* witnesses in witness.ttl.
    const KAT_ENTRIES: [(u64, u64); 4] = [
        (0x0001000000000001, 0x0A00000000000001),
        (0x0002000000000002, 0x0B00000000000002),
        (0x0003000000000003, 0x0C00000000000003),
        (0x0004000000000004, 0x0D00000000000004),
    ];

    /// The pinned cross-repo KAT head (verify.py pins the same literal).
    const KAT_HEAD: &str = "05ea1aa096f45968aacb2c996d2b541e4b9fdef24f006e0204e1fa88d33f68a5";

    /// One honest fold step: h' = BLAKE3(h || pn_be || ocel_be || tick_be64).
    fn chain_fold_step(h: [u8; DIGEST_LEN], pn: u64, ocel: u64) -> [u8; DIGEST_LEN] {
        let tick = ocel >> 56;
        let mut buf = Vec::with_capacity(DIGEST_LEN + 24);
        buf.extend_from_slice(&h);
        buf.extend_from_slice(&pn.to_be_bytes());
        buf.extend_from_slice(&ocel.to_be_bytes());
        buf.extend_from_slice(&tick.to_be_bytes());
        blake3_single_chunk(&buf)
    }

    /// Honest chain fold over `entries` (prev-hash chaining).
    fn chain_fold(entries: &[(u64, u64)]) -> [u8; DIGEST_LEN] {
        let mut h = [0u8; DIGEST_LEN];
        for &(pn, ocel) in entries {
            h = chain_fold_step(h, pn, ocel);
        }
        h
    }

    /// SABOTAGE TWIN (L124) — a chain_fold that SKIPS the prev-hash input:
    /// h' = BLAKE3(pn_be || ocel_be || tick_be64), no chaining. Each step
    /// depends only on its own entry, so the head ignores the chain prefix.
    fn chain_fold_skip_prev(entries: &[(u64, u64)]) -> [u8; DIGEST_LEN] {
        let mut h = [0u8; DIGEST_LEN];
        for &(pn, ocel) in entries {
            let tick = ocel >> 56;
            let mut buf = Vec::with_capacity(24);
            buf.extend_from_slice(&pn.to_be_bytes());
            buf.extend_from_slice(&ocel.to_be_bytes());
            buf.extend_from_slice(&tick.to_be_bytes());
            h = blake3_single_chunk(&buf);
        }
        h
    }

    /// Shared-head KAT: the honest fold over the four witnessed entries
    /// reproduces the pinned cross-repo head exactly (BLAKE3("") self-check
    /// included — published specification vector).
    #[test]
    fn shared_kat_chain_fold_head_pinned() {
        assert_eq!(
            hex32(&blake3_single_chunk(b"")),
            "af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262"
        );
        assert_eq!(hex32(&chain_fold(&KAT_ENTRIES)), KAT_HEAD);
    }

    /// Court: the skip-prev twin (a) produces a DIFFERENT head on the full
    /// witnessed fixture — the shared-KAT court refuses it — and (b) is
    /// exposed by truncation: the honest head changes when the entry list
    /// is truncated while the twin's head is invariant (it never saw the
    /// prefix), so the twin cannot even detect chain truncation.
    #[test]
    fn sabotage_twin_chain_fold_skip_prev_is_caught() {
        // (a) twin head != pinned honest head.
        let twin_head = chain_fold_skip_prev(&KAT_ENTRIES);
        assert_ne!(
            hex32(&twin_head),
            KAT_HEAD,
            "skip-prev twin reproduced the pinned KAT head — twin not caught"
        );
        assert_eq!(
            hex32(&twin_head),
            "be56d2d58a0a2bf65d8b38482b70309ccbd06cd0a0e73763f04238671c63afdd"
        );
        // (b) truncation: truncate the witnessed chain down to ONLY the
        // last entry. The honest head changes (it saw the prefix)...
        let honest_full = chain_fold(&KAT_ENTRIES);
        let honest_last_only = chain_fold(&KAT_ENTRIES[3..]);
        assert_ne!(
            hex32(&honest_full),
            hex32(&honest_last_only),
            "honest fold must be prefix-sensitive"
        );
        // ...while the twin's head is INVARIANT: it only ever hashed the
        // last entry, so it cannot detect that the first three witnessed
        // entries were truncated away.
        assert_eq!(
            hex32(&chain_fold_skip_prev(&KAT_ENTRIES[3..])),
            hex32(&twin_head),
            "twin head unexpectedly prefix-sensitive"
        );
    }
}
